_RECOVERY_STREAM_BUFFER_SIZE = 64 * 1024


class _ChainLock:
    """The shared chain coordination lock together with the chain file
    opened while holding it.

    Appends, index builds and indexed queries all compete for the same
    exclusive operating-system lock, and the chain file is opened only
    after the lock is held, so every holder observes one complete
    pre- or post-append chain. ``identity`` snapshots the opened inode's
    ``(device, inode, size)``; a re-check under the lock proves the
    document identity observed at entry.
    """

    __slots__ = ("path", "lock_fd", "fd", "identity")

    def __init__(self, path: str, timeout: float | None) -> None:
        self.path = path
        lock_path = BranchStore._recovery_chain_lock_path(path)
        self.lock_fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o644)
        try:
            BranchStore._acquire_chain_lock(self.lock_fd, timeout)
            # Open under the lock: any atomic append replace has either
            # not happened yet or already completed durably.
            self.fd = os.open(path, os.O_RDONLY)
        except BaseException:
            with contextlib.suppress(OSError):
                BranchStore._release_chain_lock(self.lock_fd)
            with contextlib.suppress(OSError):
                os.close(self.lock_fd)
            raise
        stat_result = os.fstat(self.fd)
        self.identity = (
            stat_result.st_dev,
            stat_result.st_ino,
            stat_result.st_size,
        )

    def recheck(self) -> None:
        """Raise :class:`OSError` if the opened chain inode's identity
        changed during the lock hold. Appends replace atomically under
        this same lock, so a mismatch means the file identity was never
        stable for this operation."""
        stat_result = os.fstat(self.fd)
        current = (
            stat_result.st_dev,
            stat_result.st_ino,
            stat_result.st_size,
        )
        if current != self.identity:
            raise OSError("recovery chain changed while the lock was held")

    def close(self) -> None:
        with contextlib.suppress(OSError):
            BranchStore._release_chain_lock(self.lock_fd)
        os.close(self.lock_fd)
        os.close(self.fd)


def _hash_file_fd(fd: int) -> str:
    """Stream a complete file descriptor through SHA-256 using the
    fixed read buffer, holding none of it."""
    os.lseek(fd, 0, os.SEEK_SET)
    digest = hashlib.sha256()
    while True:
        chunk = os.read(fd, _RECOVERY_STREAM_BUFFER_SIZE)
        if not chunk:
            return digest.hexdigest()
        digest.update(chunk)


class _RecoveryChainStream:
    """Forward scanner over a canonical recovery chain file with fixed
    working memory.

    Bytes are pulled through one fixed-size buffer into a rolling
    SHA-256 of the whole file. Structural tokens are matched against the
    exact canonical envelope; every frame's sequence number, predecessor
    link, embedded audit record and frame digest are authenticated. The
    only sizable materialized value is the current frame's record text,
    which the caller releases before advancing, so working memory is
    bounded by the largest single frame plus the fixed buffer.
    """

    CHUNK = _RECOVERY_STREAM_BUFFER_SIZE

    def __init__(self, fd: int, offset: int = 0) -> None:
        self._fd = fd
        os.lseek(fd, offset, os.SEEK_SET)
        self.pos = offset
        self._chunk = b""
        self._at = 0
        self._eof = False
        self.file_hash = hashlib.sha256()

    # -- low level -----------------------------------------------------

    def _refill(self) -> None:
        self._chunk = os.read(self._fd, self.CHUNK)
        self._at = 0
        if not self._chunk:
            self._eof = True

    def _next_byte(self) -> int | None:
        if self._at >= len(self._chunk):
            self._refill()
            if self._eof:
                return None
        value = self._chunk[self._at]
        self._at += 1
        self.pos += 1
        self.file_hash.update(bytes((value,)))
        return value

    def _take(self, size: int) -> bytes:
        """Consume exactly ``size`` bytes, feeding the whole-file hash;
        :class:`ValueError` at premature EOF."""
        parts = bytearray()
        while len(parts) < size:
            if self._at >= len(self._chunk):
                self._refill()
                if self._eof:
                    raise ValueError(
                        "recovery chain document is truncated"
                    )
            available = min(
                size - len(parts), len(self._chunk) - self._at
            )
            piece = self._chunk[self._at:self._at + available]
            self._at += available
            self.pos += len(piece)
            parts.extend(piece)
        data = bytes(parts)
        self.file_hash.update(data)
        return data

    def expect(self, literal: bytes, what: str) -> None:
        if self._take(len(literal)) != literal:
            raise ValueError(f"recovery chain: expected {what}")

    def expect_eof(self) -> None:
        if self._next_byte() is not None:
            raise ValueError(
                "recovery chain has trailing bytes after the document"
            )

    # -- envelope ------------------------------------------------------

    def open_envelope(self) -> None:
        """Consume the exact canonical envelope prefix through the
        opening bracket of the frames array."""
        prefix = (
            b'{"format":"'
            + BranchStore._RECOVERY_CHAIN_FORMAT.encode("utf-8")
            + b'","version":'
            + str(BranchStore._RECOVERY_CHAIN_VERSION).encode("ascii")
            + b',"frames":['
        )
        self.expect(prefix, "the canonical chain envelope header")

    # -- frames --------------------------------------------------------

    def begin_frame(self) -> int:
        """Consume a frame's opening ``{`` and return its byte offset."""
        offset = self.pos
        marker = self._next_byte()
        if marker != 0x7B:
            raise ValueError("recovery chain frame must start with '{'")
        return offset

    def frame_separator(self) -> bool:
        """Consume the byte after a frame: ``,`` means another frame
        follows; ``]`` closes the array and the document close and EOF
        are then required too. Returns whether another frame follows."""
        marker = self._next_byte()
        if marker == 0x2C:
            return True
        if marker == 0x5D:
            self.expect(b"}", "the chain document's final '}'")
            self.expect_eof()
            return False
        raise ValueError(
            "recovery chain frames must be separated by ',' and end "
            "with ']'"
        )

    def scan_frame(
        self, expected_seq: int, expected_prev: str
    ) -> dict[str, Any]:
        """Scan one complete frame after its opening brace and
        authenticate every field, returning the decoded (but not yet
        checksum-verified) record text. The record's own canonical
        spelling is proven by re-encoding the decoded value and
        comparing it with the bytes just consumed."""
        self.expect(b'"seq":', "the frame's '\"seq\"' key")
        seq = self._scan_uint()
        self.expect(b',"prev":"', "the frame's '\"prev\"' key")
        prev = self._scan_hex(64)
        self.expect(b',"record":"', "the frame's '\"record\"' key")
        record, token = self._scan_record_string()
        self.expect(b',"digest":"', "the frame's '\"digest\"' key")
        digest = self._scan_hex(64)
        self.expect(b"}", "a frame object's closing '}'")
        if seq != expected_seq:
            raise ValueError(
                f"recovery chain frame {expected_seq}: sequence numbers "
                "must be consecutive starting at 1"
            )
        if not hmac.compare_digest(prev, expected_prev):
            raise ValueError(
                f"recovery chain frame {seq}: predecessor digest does "
                "not link to the previous frame"
            )
        canonical_token = BranchStore._canonical_json(record).encode("utf-8")
        if canonical_token != token:
            raise ValueError(
                f"recovery chain frame {seq}: record is not canonical "
                "compact JSON"
            )
        if not hmac.compare_digest(
            digest,
            BranchStore._recovery_chain_frame_digest(seq, prev, record),
        ):
            raise ValueError(
                f"recovery chain frame {seq}: frame digest is invalid"
            )
        return {"seq": seq, "prev": prev, "record": record, "digest": digest}

    def _scan_uint(self) -> int:
        digits = bytearray()
        while True:
            if self._at >= len(self._chunk):
                self._refill()
                if self._eof:
                    break
            value = self._chunk[self._at]
            if not 0x30 <= value <= 0x39:
                break
            self._next_byte()
            digits.append(value)
        if not digits:
            raise ValueError("recovery chain: expected an unsigned integer")
        if len(digits) > 1 and digits[0] == 0x30:
            raise ValueError(
                "recovery chain: integer must not have a leading zero"
            )
        return int(bytes(digits))

    def _scan_hex(self, length: int) -> str:
        raw = self._take(length)
        closing = self._next_byte()
        if closing != 0x22:
            raise ValueError("recovery chain: expected a closing quote")
        if any(
            not (0x30 <= c <= 0x39 or 0x61 <= c <= 0x66) for c in raw
        ):
            raise ValueError(
                "recovery chain: expected lowercase hexadecimal characters"
            )
        return raw.decode("ascii")

    def _scan_record_string(self) -> tuple[str, bytes]:
        """Consume a frame record string's body and closing quote,
        returning ``(decoded_record_text, exact_token_bytes)``. JSON
        string syntax is validated strictly, including the prohibition
        on unescaped control characters."""
        parts = bytearray()
        while True:
            if self._at >= len(self._chunk):
                self._refill()
                if self._eof:
                    raise ValueError(
                        "recovery chain frame record is truncated"
                    )
            chunk = self._chunk
            start = self._at
            quote = chunk.find(b'"', start)
            slash = chunk.find(b"\\", start)
            control = -1
            for code in range(0x20):
                hit = chunk.find(bytes((code,)), start)
                if hit != -1 and (control == -1 or hit < control):
                    control = hit
            stops = [index for index in (quote, slash, control) if index != -1]
            if not stops:
                piece = chunk[start:]
                self._at = len(chunk)
                self.pos += len(piece)
                self.file_hash.update(piece)
                parts.extend(piece)
                continue
            target = min(stops)
            if target > start:
                piece = chunk[start:target]
                self._at = target
                self.pos += len(piece)
                self.file_hash.update(piece)
                parts.extend(piece)
            value = chunk[target]
            self._at = target + 1
            self.pos += 1
            self.file_hash.update(bytes((value,)))
            if value == 0x22:
                token = b'"' + bytes(parts) + b'"'
                try:
                    record = json.loads(token)
                except ValueError as exc:
                    raise ValueError(
                        "recovery chain frame record is not valid JSON: "
                        f"{exc}"
                    ) from exc
                if not isinstance(record, str):
                    raise ValueError(
                        "recovery chain frame record must be a JSON string"
                    )
                return record, token
            if value < 0x20:
                raise ValueError(
                    "recovery chain frame record contains an unescaped "
                    "control character"
                )
            escape = self._next_byte()
            if escape is None:
                raise ValueError(
                    "recovery chain frame record escape is truncated"
                )
            parts.append(b"\\")
            parts.append(bytes((escape,)))
            if escape == 0x75:
                hex_digits = self._take(4)
                parts.extend(hex_digits)
                if any(
                    not (
                        0x30 <= c <= 0x39
                        or 0x41 <= c <= 0x46
                        or 0x61 <= c <= 0x66
                    )
                    for c in hex_digits
                ):
                    raise ValueError(
                        "recovery chain frame record has a malformed "
                        "unicode escape"
                    )
            elif escape not in (
                0x22, 0x5C, 0x2F, 0x62, 0x66, 0x6E, 0x72, 0x74
            ):
                raise ValueError(
                    "recovery chain frame record has an invalid escape"
                )


